/*
 * RFID Inventory Tracker
 * Tracks RFID tags with LCD display and Serial logging.
 * 
 * Wiring (Arduino Uno):
 * RC522 RFID (SPI):
 *   SDA  -> Pin 10
 *   SCK  -> Pin 13
 *   MOSI -> Pin 11
 *   MISO -> Pin 12
 *   RST  -> Pin 9
 *   3V3  -> 3.3V
 *   GND  -> GND
 * 
 * LCD I2C (16x2 with PCF8574 backpack):
 *   VCC -> 5V
 *   GND -> GND
 *   SDA -> A4
 *   SCL -> A5
 * 
 * Usage: Toggle 'Tag' property on RC522 component to simulate card presence.
 *        Change 'uid' property to simulate different cards.
 */

#include <MFRC522v2.h>
#include <MFRC522DriverSPI.h>
#include <MFRC522DriverPinSimple.h>
#include <MFRC522Debug.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// RC522 pins
MFRC522DriverPinSimple ss_pin(10);
MFRC522DriverSPI driver{ss_pin};
MFRC522 mfrc522{driver};

// LCD I2C (address 0x27, 16 cols, 2 rows)
LiquidCrystal_I2C lcd(0x27, 16, 2);

// Inventory storage (max 20 tags)
String inventory[20];
int tagCount = 0;
String lastUID = "";
bool lastTagState = false;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  // Initialize RFID
  mfrc522.PCD_Init();
  MFRC522Debug::PCD_DumpVersionToSerial(mfrc522, Serial);

  // Initialize LCD
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("RFID Inventory");
  lcd.setCursor(0, 1);
  lcd.print("Tags: 0");

  Serial.println(F("\n=== RFID Inventory Tracker ==="));
  Serial.println(F("Scan tags to add to inventory."));
  Serial.println(F("Toggle 'Tag' on RC522 to simulate."));
}

void loop() {
  // Check for new card
  if (mfrc522.PICC_IsNewCardPresent()) {
    if (mfrc522.PICC_ReadCardSerial()) {
      // Build UID string
      String uidStr = "";
      for (byte i = 0; i < mfrc522.uid.size; i++) {
        if (mfrc522.uid.uidByte[i] < 0x10) uidStr += "0";
        uidStr += String(mfrc522.uid.uidByte[i], HEX);
        uidStr.toUpperCase();
        if (i < mfrc522.uid.size - 1) uidStr += ":";
      }

      // Only process if different from last read
      if (uidStr != lastUID) {
        lastUID = uidStr;

        // Check if already in inventory
        bool known = false;
        for (int i = 0; i < tagCount; i++) {
          if (inventory[i] == uidStr) {
            known = true;
            break;
          }
        }

        if (!known && tagCount < 20) {
          // New tag - add to inventory
          inventory[tagCount] = uidStr;
          tagCount++;

          Serial.print(F("[NEW] Tag #"));
          Serial.print(tagCount);
          Serial.print(F(": "));
          Serial.println(uidStr);
        } else if (known) {
          Serial.print(F("[KNOWN] "));
          Serial.println(uidStr);
        } else {
          Serial.print(F("[FULL] Cannot add: "));
          Serial.println(uidStr);
        }

        // Update LCD
        lcd.clear();
        lcd.setCursor(0, 0);
        lcd.print("Inventory: ");
        lcd.print(tagCount);
        lcd.print(F(" tags"));
        lcd.setCursor(0, 1);
        lcd.print("Last: ");
        lcd.print(uidStr.substring(0, 11)); // Fit on 16 chars

        // Halt PICC
        mfrc522.PICC_HaltA();
        mfrc522.PCD_StopCrypto1();
      }
    }
  }

  // Small delay to prevent flooding
  delay(100);
}
